<main class="section narrow"><a class="back" href="/angebote">← Alle Angebote</a><article class="detail-card"><div class="detail-top"><span class="pill"><?=App\Core\View::e($offer['category_name'])?></span><div class="price"><?=number_format((float)$offer['compensation'],2,',','.')?> €</div></div><h1><?=App\Core\View::e($offer['title'])?></h1><div class="prose"><?=nl2br(App\Core\View::e($offer['description']))?></div><div class="facts"><div><span>Erfüllungsmodell</span><strong><?=App\Core\View::e($offer['fulfillment_model'])?></strong></div><div><span>Dauer</span><strong><?=App\Core\View::e(trim(($offer['duration_value']??'').' '.($offer['duration_unit']??'')))?></strong></div></div>
<?php if($components):?><section class="card"><h2>Bestandteile dieses Kombi-Auftrags</h2><div class="worklist"><?php foreach($components as $co):?><div class="work-row"><div><b><?=App\Core\View::e($co['title'])?></b><span><?=App\Core\View::e($co['category_name'])?> · <?=App\Core\View::e($co['component_type'])?> · <?=App\Core\View::e($co['fulfillment_model'])?><?php if($co['duration_value']):?> · <?= (int)$co['duration_value'] ?> <?=App\Core\View::e($co['duration_unit']??'')?><?php endif;?></span></div><strong><?=number_format((float)$co['compensation'],2,',','.')?> €</strong></div><?php endforeach;?></div></section><?php endif;?>
<form method="post" action="/konto/angebote/<?=$offer['offer_id']?>/annehmen" class="accept-box"><?=App\Core\Csrf::field()?>
<?php if($options):?><h2>Optionen</h2><div class="option-list"><?php foreach($options as $op):?><label><span><input type="checkbox" name="options[]" value="<?=$op['id']?>"> <strong><?=App\Core\View::e($op['name'])?></strong></span><span><?=App\Core\View::e($op['description'])?></span><b><?=((float)$op['price']>0?'+ '.number_format((float)$op['price'],2,',','.').' €':'kostenlos')?></b></label><?php endforeach;?></div><?php endif;?>
<?php if($hasDigital):?><label class="check rights-check"><input type="checkbox" name="rights_acceptance" value="1" required><span>Ich akzeptiere die für diesen digitalen Auftrag geltende Rechtevereinbarung und die zweistufige Rechteübertragung.</span></label><?php endif;?>
<div class="notice">Vor der endgültigen Annahme werden Vergütung, Dauer, Nachweise, Optionen, Versand beziehungsweise digitale Abgabe und mögliche Verlängerungen als Auftrags-Snapshot gespeichert. Konkrete Empfängeradressen werden erst in der Versandphase freigegeben.</div>
<?php if($seller):?><?php if(!$seller['email_verified_at']):?><a class="btn primary wide" href="/konto/email-bestaetigen">E-Mail zuerst bestätigen</a><?php else:?><button class="btn primary wide" type="submit">Auftrag verbindlich annehmen</button><?php endif;?><?php else:?><a class="btn primary wide" href="/login">Anmelden, um Auftrag anzunehmen</a><?php endif;?></form><?php if($seller && !empty($offer['is_private']) && $offer['private_offer_status']==='pending'):?><form method="post" action="/konto/angebote/<?=$offer['offer_id']?>/ablehnen" class="decline-box"><?=App\Core\Csrf::field()?><label>Ablehnungsgrund<textarea name="reason" rows="3" required></textarea></label><button class="btn wide" type="submit">Privatangebot ablehnen</button></form><?php endif;?></article></main>